63: export function layoutBattle(state) {
64:   const w = window.innerWidth, h = window.innerHeight;
65:   const compact = w < 780;
66:   const n = state.enemies.length;
67:   const ex0 = compact ? w * 0.5 : w * 0.48;
68:   const ex1 = compact ? w * 0.9 : w * 0.88;
69:   const ey = compact ? h * 0.31 : h * 0.45;
70:   state.enemies.forEach((e, i) => {
71:     e.x = n === 1 ? (ex0 + ex1) * 0.5 : ex0 + (ex1 - ex0) * (i / (n - 1));
72:     e.y = ey + (n > 1 ? (i % 2) * h * 0.025 : 0) + (compact ? 0 : h * 0.02);
73:     e.scale = (e.scaleBase || 5) * (compact ? 0.72 : Math.min(1.15, Math.max(0.85, w / 1400)));
74:   });
75:   const alive = state.allies.filter((m) => m.hp > 0);
76:   const px0 = compact ? w * 0.13 : w * 0.2;
77:   const px1 = compact ? w * 0.43 : w * 0.43;
78:   const py = compact ? h * 0.52 : h * 0.67;
79:   alive.forEach((m, i) => {
80:     m.bx = alive.length === 1 ? (px0 + px1) / 2 : px0 + (px1 - px0) * (i / (alive.length - 1));
81:     m.by = py + (i % 2) * (compact ? 8 : 14);
82:     m.bs = compact ? 4.2 : 5.4;
83:   });
84: }
