328: export function drawBattleFrame(state, now) {
329:   const dt = state.lastTime ? Math.min(0.05, (now - state.lastTime) / 1000) : 0.016;
330:   state.lastTime = now;
331:   state.time += dt;
332:   const g = state.ctx;
333:   const w = state.w, h = state.h;
334:   if (!state.fx) state.fx = new FX();
335:   state.fx.update(dt);
336:   layoutBattle(state);
337: 
338:   // ambient particles
339:   state.ambientTimer = (state.ambientTimer || 0) + dt;
340:   const rate = state.ambient === 'snow' ? 0.05 : state.ambient === 'embers' ? 0.08 : 0.18;
341:   while (state.ambientTimer > rate) {
342:     state.ambientTimer -= rate;
343:     if (state.ambient === 'snow') {
344:       state.fx.particles.push({ x: rand(0, w), y: -10, vx: rand(-12, 12), vy: rand(30, 70), life: 0, max: rand(4, 8), size: rand(1, 3), color: '#e8f4ff', gravity: 4, glow: false, drag: 1 });
345:     } else if (state.ambient === 'embers') {
346:       state.fx.particles.push({ x: rand(0, w), y: h * 0.9, vx: rand(-10, 10), vy: rand(-50, -20), life: 0, max: rand(1.5, 3.5), size: rand(1, 3), color: chance(0.5) ? '#ff9a4a' : '#ffd27a', gravity: -6, glow: true, drag: 0.99 });
347:     } else {
348:       state.fx.particles.push({ x: rand(0, w), y: rand(0, h), vx: rand(-6, 6), vy: rand(-6, 6), life: 0, max: rand(2, 5), size: rand(1, 2), color: '#c8d0e0', gravity: 0, glow: false, drag: 1 });
349:     }
350:   }
351: 
352:   // update actor animations
353:   const all = [...state.enemies, ...state.allies];
354:   for (const a of all) {
355:     if (a.flashT > 0) a.flashT = Math.max(0, a.flashT - dt);
356:     if (a.anim) {
357:       a.anim.t += dt;
358:       if (a.anim.t >= a.anim.dur) a.anim = null;
359:     }
360:   }
361: 
362:   const shake = state.fx.offset();
363:   g.save();
364:   g.translate(shake.x, shake.y);
365:   drawBattleBG(g, w, h, state.bg, state.time);
366: 
367:   // party sprites
368:   const alive = state.allies.filter((m) => m.hp > 0);
369:   for (const m of alive) {
370:     let dx = 0, dy = 0;
371:     if (m.anim) {
372:       const p = Math.sin(clamp(m.anim.t / m.anim.dur, 0, 1) * Math.PI);
373:       dx = (m.anim.dx || 34) * p;
374:       dy = -6 * p;
375:     }
376:     const bob = Math.sin(state.time * 2 + (m.id.length)) * 1.2;
377:     drawCharacter(g, m.sprite, m.bx + dx, m.by + bob + dy, 'right', 0, m.bs, { flash: m.flashT > 0 });
378:     if (state.current === m && state.phase === 'command') {
379:       g.fillStyle = 'rgba(231,199,123,.85)';
380:       const ay = m.by - 28 * m.bs - 18 + Math.sin(state.time * 4) * 3;
381:       g.beginPath(); g.moveTo(m.bx, ay); g.lineTo(m.bx - 7, ay - 9); g.lineTo(m.bx + 7, ay - 9); g.closePath(); g.fill();
382:     }
383:   }
384:   // dead allies
385:   for (const m of state.allies.filter((x) => x.hp <= 0)) {
386:     g.save(); g.globalAlpha = 0.28; g.translate(0, 10);
387:     drawCharacter(g, m.sprite, m.bx, m.by, 'right', 0, m.bs, { alpha: 0.7 });
388:     g.restore();
389:   }
390: 
391:   // enemies
392:   for (const e of state.enemies) {
393:     if (e.hp <= 0 && !e.deadDrawn) continue;
394:     let dx = 0, dy = 0;
395:     if (e.anim) {
396:       const p = Math.sin(clamp(e.anim.t / e.anim.dur, 0, 1) * Math.PI);
397:       dx = (e.anim.dx || -34) * p;
398:     }
399:     if (e.hp <= 0) {
400:       g.save(); g.globalAlpha = Math.max(0, 0.35 - (e.deadT || 0) * 0.1);
401:       drawEnemy(g, e.id, e.x, e.y + 8, e.scale, state.time, { alpha: 0.35, bob: false });
402:       g.restore();
403:       e.deadT = (e.deadT || 0) + dt;
404:       continue;
405:     }
406:     drawEnemy(g, e.id, e.x + dx, e.y, e.scale, state.time, { flash: e.flashT > 0, phase: e.bobPhase });
407:     // HP bar
408:     const bw = clamp(e.scale * 26, 64, 170);
409:     const bx = e.x - bw / 2, by = e.y - (e.scale * 48) - 18;
410:     g.fillStyle = 'rgba(4,7,14,.8)';
411:     g.fillRect(bx - 2, by - 2, bw + 4, 14);
412:     g.fillStyle = '#3a1520'; g.fillRect(bx, by, bw, 6);
413:     const pct = clamp(e.hp / e.maxHp, 0, 1);
414:     const grd = g.createLinearGradient(bx, by, bx + bw, by);
415:     grd.addColorStop(0, '#8e2737'); grd.addColorStop(0.6, '#e35f72'); grd.addColorStop(1, '#ff9aa7');
416:     g.fillStyle = grd; g.fillRect(bx, by, bw * pct, 6);
417:     g.strokeStyle = 'rgba(231,199,123,.35)'; g.lineWidth = 1; g.strokeRect(bx + 0.5, by + 0.5, bw - 1, 5);
418:     g.font = '700 13px "VT323", monospace';
419:     g.textAlign = 'center'; g.textBaseline = 'bottom';
420:     g.fillStyle = 'rgba(8,8,14,.8)'; g.fillText(e.name, e.x + 1, by - 4);
421:     g.fillStyle = '#e8e0cc'; g.fillText(e.name, e.x, by - 5);
422:     // target marker
423:     if (state.hoverTarget === e) {
424:       g.fillStyle = '#ffe6a3';
425:       const ay = by - 20 + Math.sin(state.time * 6) * 3;
426:       g.beginPath(); g.moveTo(e.x, ay + 10); g.lineTo(e.x - 8, ay); g.lineTo(e.x + 8, ay); g.closePath(); g.fill();
427:     }
428:   }
429:   // ally target marker
430:   if (state.hoverTarget && !state.hoverTarget.isEnemy) {
431:     const m = state.hoverTarget;
432:     g.strokeStyle = 'rgba(255,230,163,.9)'; g.lineWidth = 3;
433:     g.beginPath(); g.ellipse(m.bx, m.by, 30, 8, 0, 0, Math.PI * 2); g.stroke();
434:   }
435: 
436:   state.fx.draw(g);
437:   g.restore();
438: }
