ctx:
```
const ctx = {
 chapter(i){ game.chapter=i; game.chapterLabel=`Capítulo ${CHAPTERS[i].n}`; ui.updateHUD(game); },
 quest(text){ if(game.quest!==text){ game.journal.forEach(j=>j.active=false); game.journal.push({chapter:CHAPTERS[game.chapter].n,text,active:true}); if(game.journal.length>14)game.journal.shift(); } game.quest=text; ui.setQuest(text); },
