143: function saveGame(silent = true) {
144:   if (!game || !player) return false;
145:   const data = {
146:     version: 1,
147:     flags: game.flags,
148:     triggers: game.triggers,
149:     chests: game.chests,
150:     seen: game.seen,
151:     party: game.party,
152:     gold: game.gold,
153:     inventory: game.inventory,
154:     chapter: game.chapter,
155:     quest: game.quest,
156:     journal: game.journal,
157:     playTime: game.playTime,
158:     battlesWon: game.battlesWon,
159:     completed: !!game.completed,
160:     mapId: game.mapId,
161:     mapName: game.mapName,
162:     player: { x: player.x, y: player.y, dir: player.dir },
163:   };
164:   const ok = Store.set(SAVE_KEY, data);
165:   if (ok && !silent) audio.sfx('save');
166:   return ok;
