169: function readSave() {
170:   const save = Store.get(SAVE_KEY, null);
171:   if (!save || save.version !== 1) return null;
172:   save.label = `Capítulo ${CHAPTERS[save.chapter]?.n || 'I'} · ${save.mapName || 'Brumalva'}`;
