176: // ------------------------------------------------------------------ map
177: function setMap(id, x, y, dir = 'up') {
178:   const map = getMap(id) || MAPS.village;
179:   currentMap = map;
180:   player = {
181:     x, y, dir,
182:     fromX: x, fromY: y,
183:     moving: false, t: 1, frame: 0,
184:   };
185:   groundCanvas = renderGround(map);
186:   ambientType = map.ambient || 'dust';
187:   encounterSteps = 0;
188:   game.mapId = map.id;
189:   game.mapName = map.name;
190:   audio.playMusic(map.bgm || 'field');
191: }
