345: // ------------------------------------------------------------------ story context
346: const storyCtx = {
347:   chapter(index) {
348:     game.chapter = index;
349:     game.chapterLabel = `Capítulo ${CHAPTERS[index]?.n || 'I'}`;
350:     ui.updateHUD(game);
351:   },
352:   quest(text) {
353:     if (game.quest !== text) {
354:       for (const j of game.journal) j.active = false;
355:       game.journal.push({ chapter: CHAPTERS[game.chapter]?.n || 'I', text, active: true });
356:       if (game.journal.length > 16) game.journal.shift();
357:     }
358:     game.quest = text;
359:     ui.setQuest(text);
360:   },
361:   join(id, level) {
362:     if (game.party.some((m) => m.id === id)) { storyCtx.levelTo(id, level); return; }
363:     const m = makeMember(id, level);
364:     m.hp = m.maxHp;
365:     m.mp = m.maxMp;
366:     game.party.push(m);
367:     ui.updateHUD(game);
368:     ui.toast(`${m.name} entrou no grupo!`, 'gold', '✦');
369:     audio.sfx('levelup');
370:   },
371:   levelTo(id, level) {
372:     const m = game.party.find((x) => x.id === id);
373:     if (!m) return;
374:     while (m.level < level) levelUpMember(m, 1);
375:     m.hp = m.maxHp;
376:     m.mp = m.maxMp;
377:     ui.updateHUD(game);
378:   },
379:   healAll(pct = 1) {
380:     for (const m of game.party) {
381:       m.hp = Math.max(1, Math.round(m.maxHp * pct));
382:       m.mp = Math.round(m.maxMp * pct);
383:       m.status = {};
384:       m.buffs = [];
385:       m.defending = false;
386:     }
387:     ui.updateHUD(game);
388:   },
389:   give(id, n = 1) {
390:     game.inventory[id] = (game.inventory[id] || 0) + n;
391:     ui.updateHUD(game);
392:   },
393:   async shop(stock, title) { await openShop(stock, title); },
394:   async goto(id, x, y, dir, opts) { await gotoMap(id, x, y, dir, opts); },
395:   async battle(ids, opts) { return await runBattle(ids, opts); },
396:   async modal(opts) { return await ui.modal(opts); },
397:   async ending() {
398:     game.completed = true;
399:     game.playTimeLabel = formatTime(game.playTime);
400:     await ui.ending(game);
401:   },
402:   save() { saveGame(true); },
403: };
