405: let storyId = 0;
406: async function runStory(name) {
407:   if (!name) return;
408:   const blocker = `story-${++storyId}`;
409:   block(blocker);
410:   try {
411:     const result = await runScript(name, game, storyCtx);
412:     if (result === 'title') {
413:       if (game.completed) saveGame(true);
414:       endSession('title');
415:       return;
416:     }
417:     if (!sessionEnded) saveGame(true);
418:   } catch (err) {
419:     if (err === TITLE_EXIT) { endSession('title'); return; }
420:     console.error('Story error:', name, err);
421:   } finally {
422:     unblock(blocker);
423:   }
424: }
425: 
426: async function gotoMap(id, x, y, dir = 'up', opts = {}) {
427:   if (transitioning) return;
428:   transitioning = true;
429:   block('transition');
430:   try {
431:     await ui.fadeOut(opts.fade ?? 420);
432:     setMap(id, x, y, dir);
433:     await wait(70);
434:     await ui.fadeIn(opts.fade ?? 420);
435:   } finally {
436:     unblock('transition');
437:     transitioning = false;
438:   }
439:   if (!opts.skipEnter) {
440:     const map = currentMap;
441:     const key = `enter:${map.id}`;
442:     if (map.onEnter && !game.seen[key]) {
443:       game.seen[key] = true;
444:       await runStory(map.onEnter);
445:     }
446:   }
447: }
