471: async function openShop(stock, title) {
472:   if (mode !== 'explore' || isBusy()) return;
473:   block('shop');
474:   try {
475:     await shopMenu(game, stock, title);
476:   } finally {
477:     unblock('shop');
478:     ui.updateHUD(game);
479:   }
480: }
481: 
482: async function openPause() {
483:   if (mode !== 'explore' || isBusy()) return;
484:   block('pause');
485:   try {
486:     const result = await pauseMenu(game, { save: () => saveGame(true) });
487:     if (result === 'title') endSession('title');
488:   } finally {
489:     unblock('pause');
490:   }
491: }
