499: // ------------------------------------------------------------------ rendering
500: function drawWorld() {
501:   const map = currentMap;
502:   if (!map || !groundCanvas) return;
503:   g.setTransform(dpr, 0, 0, dpr, 0, 0);
504:   g.clearRect(0, 0, VW, VH);
505: 
506:   const zoom = computeZoom(map);
507:   const vw = VW / zoom;
508:   const vh = VH / zoom;
509:   const pp = playerPixel();
510:   const mw = map.w * 16;
511:   const mh = map.h * 16;
512:   let camX = pp.x - vw / 2;
513:   let camY = pp.y - vh / 2;
514:   camX = mw <= vw ? (mw - vw) / 2 : clamp(camX, 0, mw - vw);
515:   camY = mh <= vh ? (mh - vh) / 2 : clamp(camY, 0, mh - vh);
516: 
517:   g.save();
518:   g.translate(-camX * zoom, -camY * zoom);
519:   g.scale(zoom, zoom);
520:   g.imageSmoothingEnabled = false;
521:   g.drawImage(groundCanvas, 0, 0);
522: 
523:   const drawables = [];
524: 
525:   for (const p of map.props) {
526:     if (p.hidden) continue;
527:     const open = p.openFlag ? !!game.flags[p.openFlag] : false;
528:     drawables.push({
529:       y: propBaseY(p),
530:       draw: () => drawProp(g, p, map.theme, time, { open }),
531:     });
532:   }
533:   for (const c of map.chests) {
534:     if (!chestPresent(c)) continue;
535:     drawables.push({
536:       y: (c.y + 1) * 16,
537:       draw: () => drawChest(g, c.x, c.y, !!game.chests[c.id], time),
538:     });
539:   }
540:   for (const n of map.npcs) {
541:     if (!npcPresent(n)) continue;
542:     drawables.push({
543:       y: (n.y + 1) * 16,
544:       draw: () => {
545:         const bob = Math.sin(time * 1.6 + n.x * 0.7) * 0.6;
546:         drawCharacter(g, n.sprite, n.x * 16 + 8, n.y * 16 + 16 + bob, n.dir || 'down', 0, 1);
547:       },
548:     });
549:   }
550: 
551:   const pp2 = playerPixel();
552:   const walkingFrame = player.moving ? (Math.floor(player.t * 4) % 2) * 2 : 0;
553:   drawables.push({
554:     y: pp2.y,
555:     draw: () => drawCharacter(g, 'kael', pp2.x, pp2.y, player.dir, walkingFrame, 1, { alpha: 1 }),
556:   });
557:   drawables.sort((a, b) => a.y - b.y);
558:   for (const d of drawables) d.draw();
559: 
560:   g.restore();
561: 
562:   drawWaterShimmer(g, map, { x: camX, y: camY, w: vw, h: vh }, time, zoom);
563:   drawAmbient();
564:   drawLighting(camX, camY, zoom);
565: }
566: 
567: function drawAmbient() {
568:   const type = ambientType;
569:   g.save();
570:   if (type === 'snow') {
571:     for (let i = 0; i < 90; i++) {
572:       const x = ((hash2(i, 1) * VW + Math.sin(time * 0.5 + i) * 26) % VW + VW) % VW;
573:       const y = ((hash2(i, 2) * VH + time * (22 + (i % 5) * 9)) % VH + VH) % VH;
574:       g.globalAlpha = 0.35 + (i % 4) * 0.12;
575:       g.fillStyle = '#eaf6ff';
576:       const s = i % 7 === 0 ? 2 : 1;
577:       g.fillRect(x, y, s, s);
578:     }
579:   } else if (type === 'embers') {
580:     for (let i = 0; i < 38; i++) {
581:       const x = ((hash2(i, 3) * VW + Math.sin(time * 0.8 + i * 1.7) * 20) % VW + VW) % VW;
582:       const y = ((hash2(i, 4) * VH - time * (14 + (i % 6) * 7)) % VH + VH) % VH;
583:       g.globalAlpha = 0.22 + Math.sin(time * 2 + i) * 0.16;
584:       g.fillStyle = i % 3 === 0 ? '#ffd27a' : '#ff8a4a';
585:       g.fillRect(x, y, 2, 2);
586:     }
587:   } else if (type === 'fireflies') {
588:     for (let i = 0; i < 26; i++) {
589:       const x = ((hash2(i, 5) * VW + Math.sin(time * 0.6 + i) * 45) % VW + VW) % VW;
590:       const y = ((hash2(i, 6) * VH + Math.cos(time * 0.5 + i * 1.3) * 30) % VH + VH) % VH;
591:       g.globalAlpha = 0.3 + Math.sin(time * 2.4 + i * 1.9) * 0.28;
592:       g.fillStyle = '#c8ffb0';
593:       g.fillRect(x, y, 2, 2);
594:     }
595:   } else if (type === 'leaves') {
596:     for (let i = 0; i < 24; i++) {
597:       const x = ((hash2(i, 7) * VW + time * (12 + (i % 4) * 8)) % (VW + 40)) - 20;
598:       const y = ((hash2(i, 8) * VH + Math.sin(time * 0.9 + i) * 20) % VH + VH) % VH;
599:       g.globalAlpha = 0.28 + (i % 3) * 0.12;
600:       g.fillStyle = i % 2 ? '#a8c47a' : '#d8b46a';
601:       g.fillRect(x, y, 3, 2);
602:     }
603:   } else {
604:     for (let i = 0; i < 34; i++) {
605:       const x = ((hash2(i, 9) * VW + Math.sin(time * 0.3 + i) * 14) % VW + VW) % VW;
606:       const y = ((hash2(i, 10) * VH + Math.cos(time * 0.22 + i) * 16) % VH + VH) % VH;
607:       g.globalAlpha = 0.12 + (i % 4) * 0.05;
608:       g.fillStyle = '#d8d0b8';
609:       g.fillRect(x, y, 1, 1);
610:     }
611:   }
612:   g.restore();
613: }
614: 
615: function drawLighting(camX, camY, zoom) {
616:   const th = THEMES[currentMap.theme];
617:   if (!th?.dark) return;
618:   const pp = playerPixel();
619:   const px = (pp.x - camX) * zoom;
620:   const py = (pp.y - camY) * zoom;
621:   g.save();
622:   for (const p of currentMap.props) {
623:     if (!['torch', 'campfire', 'crystal', 'lamp', 'altar', 'portal'].includes(p.t)) continue;
624:     const wx = (p.x * 16 + 8 - camX) * zoom;
625:     const wy = (p.y * 16 + 8 - camY) * zoom;
626:     const radius = (p.t === 'campfire' ? 110 : p.t === 'lamp' ? 70 : 60) * zoom;
627:     const grd = g.createRadialGradient(wx, wy, 2, wx, wy, radius);
628:     grd.addColorStop(0, 'rgba(255,200,120,.22)');
629:     grd.addColorStop(1, 'rgba(255,180,90,0)');
630:     g.globalCompositeOperation = 'lighter';
631:     g.fillStyle = grd;
632:     g.fillRect(wx - radius, wy - radius, radius * 2, radius * 2);
633:   }
634:   g.restore();
635: 
636:   const grd = g.createRadialGradient(px, py, 60, px, py, Math.max(VW, VH) * 0.78);
637:   grd.addColorStop(0, 'rgba(2,4,10,0)');
638:   grd.addColorStop(0.55, 'rgba(2,4,10,.16)');
639:   grd.addColorStop(1, 'rgba(2,4,10,.6)');
640:   g.fillStyle = grd;
641:   g.fillRect(0, 0, VW, VH);
642: }
643: 
644: function drawTitle() {
645:   g.setTransform(dpr, 0, 0, dpr, 0, 0);
646:   g.clearRect(0, 0, VW, VH);
647:   drawTitleBG(g, VW, VH, time, game?.completed ? 'ending' : 'title');
648: }
649: 
650: // ------------------------------------------------------------------ frame loop
651: function loop(now) {
652:   const dt = lastFrame ? Math.min(0.05, (now - lastFrame) / 1000) : 0.016;
653:   lastFrame = now;
654:   time += dt;
655: 
656:   if (mode === 'title') {
657:     drawTitle();
658:   } else if (mode === 'battle') {
659:     const b = getActiveBattle();
660:     g.setTransform(dpr, 0, 0, dpr, 0, 0);
661:     g.clearRect(0, 0, VW, VH);
662:     if (b) {
