11: const line = (rows, x1, y1, x2, y2, ch, width = 2) => {
12:   const steps = Math.max(Math.abs(x2 - x1), Math.abs(y2 - y1));
13:   for (let i = 0; i <= steps; i++) {
14:     const t = steps ? i / steps : 0;
15:     const x = Math.round(x1 + (x2 - x1) * t);
16:     const y = Math.round(y1 + (y2 - y1) * t);
17:     setRect(rows, x - Math.floor(width / 2), y - Math.floor(width / 2), width, width, ch);
18:   }
19: };
